#!/usr/bin/env python3
"""Truth table harness: run /workspace/executable with controlled env and pipe-or-pty stdout."""
import os, pty, sys, subprocess, itertools, json

EXE = "/workspace/executable"
FIX = "/tmp/probe/work-11/all.json"

def run_pipe(args, env):
    p = subprocess.run([EXE]+args, stdout=subprocess.PIPE, stderr=subprocess.PIPE,
                       stdin=subprocess.DEVNULL, env=env)
    return p.stdout, p.stderr, p.returncode

def run_pty(args, env, pty_stderr=False):
    m, s = pty.openpty()
    if pty_stderr:
        me, se = pty.openpty()
        errfd = se
    else:
        errfd = subprocess.PIPE
    p = subprocess.Popen([EXE]+args, stdout=s, stderr=errfd,
                         stdin=subprocess.DEVNULL, env=env)
    os.close(s)
    if pty_stderr: os.close(se)
    out = b""
    while True:
        try:
            d = os.read(m, 65536)
        except OSError:
            break
        if not d: break
        out += d
    p.wait(); os.close(m)
    if pty_stderr:
        err = b""
        try:
            while True:
                d = os.read(me, 65536)
                if not d: break
                err += d
        except OSError: pass
        os.close(me)
    else:
        err = p.stderr.read()
    return out, err, p.returncode

def mkenv(**over):
    e = dict(os.environ)
    for k in ("NO_COLOR","CLICOLOR","CLICOLOR_FORCE","TERM","FORCE_COLOR"):
        e.pop(k, None)
    for k,v in over.items():
        if v is None: e.pop(k, None)
        else: e[k]=v
    return e

if __name__ == "__main__":
    flagsets = [[], ["-c"], ["-m"], ["-c","-m"], ["-m","-c"]]
    nocolors = [("unset",None),("1","1"),('""',""),("0","0")]
    terms = [("xterm","xterm"),("dumb","dumb"),("unset",None)]
    print("%-10s %-6s %-9s %-6s %-6s" % ("FLAGS","STDOUT","NO_COLOR","TERM","COLOR?"))
    for fs in flagsets:
        for nn,nv in nocolors:
            for tn,tv in terms:
                env = mkenv(NO_COLOR=nv, TERM=tv)
                for mode in ("pipe","tty"):
                    fn = run_pipe if mode=="pipe" else run_pty
                    out,err,rc = fn(fs+[FIX], env)
                    has = b"\x1b[" in out
                    print("%-10s %-6s %-9s %-6s %-6s rc=%d" % (" ".join(fs) or "(none)", mode, nn, tn, "COLOR" if has else "-", rc))
PYEOF
