#!/usr/bin/env python3
"""Read stdin bytes, print per-line repr."""
import sys
d = sys.stdin.buffer.read()
lines = d.split(b"\n")
for i, l in enumerate(lines):
    if i == len(lines) - 1 and l == b"":
        print("<final newline present>")
    else:
        print(repr(l))
if lines[-1] != b"":
    print("<NO final newline>")
print("total_bytes=%d" % len(d))

